-- Each kind of shape is its own table (its own "type")...
CREATE TABLE rectangle (width INTEGER NOT NULL, height INTEGER NOT NULL);
CREATE TABLE triangle  (base  INTEGER NOT NULL, height INTEGER NOT NULL);

INSERT INTO rectangle VALUES (3, 4);
INSERT INTO triangle  VALUES (10, 3);

-- ...and a view gives them a common "area" interface.
CREATE VIEW shape_area (shape, area) AS
  SELECT 'Rectangle', width * height   FROM rectangle
  UNION ALL
  SELECT 'Triangle',  base * height / 2 FROM triangle;

SELECT shape || ': ' || area FROM shape_area ORDER BY shape;
